public void processOperation()
{
    SalesTable salesTable;

    while select forUpdate salesTable
        where salesTable.BatchJobStatus == MZNAG_BatchJobStatus::Started
    { ttsbegin;
        if (salesTable.SalesStatus == SalesStatus::Backorder)
        {
            salesTable.BatchJobStatus = MZNAG_BatchJobStatus::Ended;
            salesTable.update();
        }
       ttscommit;
    }
}
